import sys
M = 1000000007
def fib(n):
    a, b = 0, 1
    for c in bin(n)[2:]:
        t = a * (2 * b - a) % M
        u = (a * a + b * b) % M
        if c == '1':
            a, b = u, (t + u) % M
        else:
            a, b = t, u
    return a
def main():
    d = sys.stdin.read().split()
    c = {}
    out = []
    for s in d:
        r = c.get(s)
        if r is None:
            r = c[s] = fib(int(s))
        out.append(r)
    sys.stdout.write("\n".join(map(str, out)) + ("\n" if out else ""))
main()

import sys
M = 1000000007
P = 2 * (M + 1)  # Pisano period of M divides P since M % 5 == 2
def fib(n):
    a, b = 0, 1
    for c in bin(n)[2:]:
        t = a * (2 * b - a) % M
        u = (a * a + b * b) % M
        if c == '1':
            a, b = u, (t + u) % M
        else:
            a, b = t, u
    return a
def main():
    d = sys.stdin.read().split()
    c = {}
    out = []
    for s in d:
        r = c.get(s)
        if r is None:
            r = c[s] = fib(int(s) % P)
        out.append(r)
    sys.stdout.write("\n".join(map(str, out)) + ("\n" if out else ""))
main()
